import("/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs").then(async (m)=>{
 const g=m.load("build.nbt");
 for (const y of [0,1,2,3,4,5,6]) { const row=[]; for (let z=14;z<=18;z++){ let s=""; for(let x=86;x<=90;x++){ const c=g.get?g.get(x,y,z):null; s+=(c? (Array.isArray(c)?c[0]:(c.name||c)):"?").toString().slice(0,10).padEnd(11);} row.push("z"+z+" "+s);} console.log("y"+y+"\n"+row.join("\n")); }
});' 2>&1 | head -60

